class Solution {
    using ll = long long;

    struct Fenwick {
        int n;
        vector<int> cnt;
        vector<ll> sum;
        const vector<int>& values;

        Fenwick(const vector<int>& v)
            : n((int)v.size()),
              cnt(n + 1, 0),
              sum(n + 1, 0),
              values(v) {}

        void add(int idx, int delta) {
            int val = values[idx - 1];

            for (int i = idx; i <= n; i += i & -i) {
                cnt[i] += delta;
                sum[i] += 1LL * delta * val;
            }
        }

        // Find the 1-based index of the kth smallest value.
        int kth(int k) const {
            int idx = 0;
            int step = 1;

            while ((step << 1) <= n)
                step <<= 1;

            for (; step > 0; step >>= 1) {
                int next = idx + step;

                if (next <= n && cnt[next] < k) {
                    idx = next;
                    k -= cnt[next];
                }
            }

            return idx + 1;
        }

        // Sum of the smallest k elements.
        ll smallestSum(int k) const {
            if (k == 0)
                return 0;

            int idx = 0;
            int step = 1;
            ll result = 0;

            while ((step << 1) <= n)
                step <<= 1;

            for (; step > 0; step >>= 1) {
                int next = idx + step;

                if (next <= n && cnt[next] < k) {
                    idx = next;
                    k -= cnt[next];
                    result += sum[next];
                }
            }

            return result + 1LL * k * values[idx];
        }
    };

public:
    long long maxSum(vector<int>& nums, int k) {
        int n = (int)nums.size();

        vector<int> values = nums;
        sort(values.begin(), values.end());
        values.erase(
            unique(values.begin(), values.end()),
            values.end()
        );

        vector<int> id(n);

        for (int i = 0; i < n; ++i) {
            id[i] = lower_bound(
                values.begin(), values.end(), nums[i]
            ) - values.begin() + 1;
        }

        ll answer = LLONG_MIN;

        for (int left = 0; left < n; ++left) {
            Fenwick inside(values);
            Fenwick outside(values);

            for (int i = 0; i < n; ++i)
                outside.add(id[i], 1);

            ll windowSum = 0;
            ll outsideSum = 0;

            for (int x : nums)
                outsideSum += x;

            int swaps = 0;

            for (int right = left; right < n; ++right) {
                inside.add(id[right], 1);
                outside.add(id[right], -1);

                windowSum += nums[right];
                outsideSum -= nums[right];

                int len = right - left + 1;
                int out = n - len;

                // The optimal number of beneficial swaps
                // changes by at most one when right advances.
                if (swaps < k &&
                    swaps < len &&
                    swaps < out &&
                    inside.kth(swaps + 1) <
                    outside.kth(out - swaps)) {

                    ++swaps;

                } else if (swaps > 0 &&
                           inside.kth(swaps) >=
                           outside.kth(out - swaps + 1)) {

                    --swaps;
                }

                ll removed = inside.smallestSum(swaps);

                ll incoming = outsideSum -
                    outside.smallestSum(out - swaps);

                ll current = windowSum
                           - removed
                           + incoming;

                answer = max(answer, current);
            }
        }

        return answer;
    }
};
